cat <<'SQL' | sqlplus -s / as sysdba
SET HEADING OFF FEEDBACK OFF PAGESIZE 0 LINESIZE 300 TRIMSPOOL ON
WHENEVER SQLERROR EXIT SQL.SQLCODE
ALTER SESSION SET CONTAINER = FREEPDB1;
CREATE OR REPLACE DIRECTORY rdlab_bk AS '/backups';
GRANT READ, WRITE ON DIRECTORY rdlab_bk TO lab;
EXIT
SQL

cat <<'SQL' | sqlplus -s / as sysdba
SET HEADING OFF FEEDBACK OFF PAGESIZE 0 LINESIZE 300 TRIMSPOOL ON
WHENEVER SQLERROR EXIT SQL.SQLCODE
ALTER SESSION SET CONTAINER = FREEPDB1;
BEGIN EXECUTE IMMEDIATE 'DROP USER lab_restore CASCADE'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
CREATE USER lab_restore IDENTIFIED BY labpass QUOTA UNLIMITED ON USERS;
GRANT CONNECT, RESOURCE, CREATE VIEW TO lab_restore;

cat <<'SQL' | sqlplus -s / as sysdba
SET HEADING OFF FEEDBACK OFF PAGESIZE 0 LINESIZE 300 TRIMSPOOL ON
WHENEVER SQLERROR EXIT SQL.SQLCODE
ALTER SESSION SET CONTAINER = FREEPDB1;
GRANT EXECUTE ON DBMS_FLASHBACK TO lab;
GRANT FLASHBACK ANY TABLE TO lab;
EXIT
SQL
